messages.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.UserMessageExpression",
  "description": "Expression variant of [`UserMessage`] for dynamic content.",
  "type": "object",
  "properties": {
    "content": {
      "description": "The message content expression.",
      "$ref": "functions.expression.WithExpression.agent.completions.message.RichContentExpression"
    },
    "name": {
      "description": "Optional name expression.",
      "anyOf": [
        {
          "$ref": "functions.expression.WithExpression.Nullable_string"
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "content"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.Special",
  "description": "Predefined expression behaviors that require no user-authored code.",
  "oneOf": [
    {
      "description": "Returns the params input as-is.",
      "type": "string",
      "const": "input"
    },
    {
      "description": "Returns the params output as-is.",
      "type": "string",
      "const": "output"
    },
    {
      "description": "L1-normalizes the output. Scalar/Err pass through.\nVector: L1 normalize. Vectors: L1 normalize each.",
      "type": "string",
      "const": "task_output_l1_normalized"
    },
    {
      "description": "Weighted sum of the output. Vector → Scalar. Vectors → Vector.",
      "type": "string",
      "const": "task_output_weighted_sum"
    },
    {
      "description": "Returns the length of input['items'] as u64",
      "type": "string",
      "const": "input_items_output_length"
    },
    {
      "description": "Splits an input containing items and optionally context into multiple inputs",
      "type": "string",
      "const": "input_items_optional_context_split"
    },
    {
      "description": "Merges multiple inputs containing items and optionally context into a single input",
      "type": "string",
      "const": "input_items_optional_context_merge"
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.ImageUrlDetail",
  "description": "Detail level for image processing.",
  "oneOf": [
    {
      "description": "Let the model decide the detail level.",
      "type": "string",
      "const": "auto"
    },
    {
      "description": "Low detail mode (faster, less tokens).",
      "type": "string",
      "const": "low"
    },
    {
      "description": "High detail mode (more accurate, more tokens).",
      "type": "string",
      "const": "high"
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.FileInputSchema",
  "description": "Schema for a file input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected file.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ObjectInputSchema",
  "description": "Schema for an object input with named properties.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the object.",
      "type": [
        "string",
        "null"
      ]
    },
    "properties": {
      "description": "Schema for each property in the object.",
      "type": "object",
      "additionalProperties": {
        "$ref": "functions.expression.InputSchema"
      }
    },
    "required": {
      "description": "List of property names that must be present.",
      "type": [
        "array",
        "null"
      ],
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "properties"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.NumberInputSchema",
  "description": "Schema for a floating-point number input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the number.",
      "type": [
        "string",
        "null"
      ]
    },
    "minimum": {
      "description": "Minimum allowed value (inclusive).",
      "type": [
        "number",
        "null"
      ],
      "format": "double"
    },
    "maximum": {
      "description": "Maximum allowed value (inclusive).",
      "type": [
        "number",
        "null"
      ],
      "format": "double"
    }
  }
}
